#include <torch/extension.h>
torch::Tensor cute_gemv_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

#define ROWS_PER_BLOCK 32
#define TILE_K4 256
#define SPLIT_K 8
#define THREADS_PER_BLOCK 256
#define WARP_SIZE 32
#define NUM_WARPS (THREADS_PER_BLOCK / WARP_SIZE)
#define ROWS_PER_WARP (ROWS_PER_BLOCK / NUM_WARPS)
// Each block processes ROWS_PER_BLOCK rows of A against the shared vector B.
// B is staged into shared memory once per K-tile and reused across all rows
// handled by the block, cutting redundant global memory traffic for B by a
// factor of ROWS_PER_BLOCK compared to the naive one-row-per-block scheme.
__global__ void gemv_kernel(const float* __restrict__ A,
                             const float* __restrict__ B,
                             float* __restrict__ C,
                             int M, int K)
{
  int row_start = blockIdx.x * ROWS_PER_BLOCK;
  if (row_start >= M) return;
  int rows = M - row_start;
  if (rows > ROWS_PER_BLOCK) rows = ROWS_PER_BLOCK;
  __shared__ float4 sB4[2][TILE_K4];
  // Warp-level tiling: each warp owns a fixed subset of rows within the
  // block. This cuts the per-thread accumulator footprint from
  // ROWS_PER_BLOCK down to ROWS_PER_WARP, drastically reducing register
  // pressure and improving occupancy, while still sharing the staged B
  // tile across all warps in the block.
  int warp_id = threadIdx.x / WARP_SIZE;
  int lane_id = threadIdx.x % WARP_SIZE;
  float sum[ROWS_PER_WARP];
  #pragma unroll
  for (int r = 0; r < ROWS_PER_WARP; ++r) sum[r] = 0.0f;
  int K4 = K / 4;
  int split_id = blockIdx.y;
  int k4_per_split = (K4 + SPLIT_K - 1) / SPLIT_K;
  int k4_start = split_id * k4_per_split;
  int k4_end = k4_start + k4_per_split;
  if (k4_end > K4) k4_end = K4;
  if (k4_start > K4) k4_start = K4;
  const float4* B4 = reinterpret_cast<const float4*>(B);
  int cur_buf = 0;
  if (k4_start < k4_end) {
    int first_tile_len = k4_end - k4_start;
    if (first_tile_len > TILE_K4) first_tile_len = TILE_K4;
    for (int i = threadIdx.x; i < first_tile_len; i += blockDim.x) {
      sB4[cur_buf][i] = B4[k4_start + i];
    }
    __syncthreads();
  }
  for (int k0 = k4_start; k0 < k4_end; k0 += TILE_K4) {
    int tile_len = k4_end - k0;
    if (tile_len > TILE_K4) tile_len = TILE_K4;
    int next_k0 = k0 + TILE_K4;
    int next_buf = 1 - cur_buf;
    int next_tile_len = 0;
    if (next_k0 < k4_end) {
      next_tile_len = k4_end - next_k0;
      if (next_tile_len > TILE_K4) next_tile_len = TILE_K4;
      for (int i = threadIdx.x; i < next_tile_len; i += blockDim.x) {
        sB4[next_buf][i] = B4[next_k0 + i];
      }
    }
    #pragma unroll
    for (int rr = 0; rr < ROWS_PER_WARP; ++rr) {
      int r = warp_id * ROWS_PER_WARP + rr;
      if (r >= rows) continue;
      const float4* Arow4 = reinterpret_cast<const float4*>(A + (size_t)(row_start + r) * K) + k0;
      float local = 0.0f;
      int i = lane_id;
      int stride1 = WARP_SIZE;
      int stride2 = 2 * WARP_SIZE;
      int stride3 = 3 * WARP_SIZE;
      int stride4 = 4 * WARP_SIZE;
      for (; i + stride3 < tile_len; i += stride4) {
        float4 a0 = Arow4[i];
        float4 a1 = Arow4[i + stride1];
        float4 a2 = Arow4[i + stride2];
        float4 a3 = Arow4[i + stride3];
        float4 b0 = sB4[cur_buf][i];
        float4 b1 = sB4[cur_buf][i + stride1];
        float4 b2 = sB4[cur_buf][i + stride2];
        float4 b3 = sB4[cur_buf][i + stride3];
        local += a0.x * b0.x + a0.y * b0.y + a0.z * b0.z + a0.w * b0.w;
        local += a1.x * b1.x + a1.y * b1.y + a1.z * b1.z + a1.w * b1.w;
        local += a2.x * b2.x + a2.y * b2.y + a2.z * b2.z + a2.w * b2.w;
        local += a3.x * b3.x + a3.y * b3.y + a3.z * b3.z + a3.w * b3.w;
      }
      for (; i < tile_len; i += stride1) {
        float4 a4 = Arow4[i];
        float4 b4 = sB4[cur_buf][i];
        local += a4.x * b4.x + a4.y * b4.y + a4.z * b4.z + a4.w * b4.w;
      }
      sum[rr] += local;
    }
    __syncthreads();
    cur_buf = next_buf;
  }
  // Remainder (K not divisible by 4), handled only by the last K-split
  if (split_id == SPLIT_K - 1) {
    int rem_start = K4 * 4;
    #pragma unroll
    for (int rr = 0; rr < ROWS_PER_WARP; ++rr) {
      int r = warp_id * ROWS_PER_WARP + rr;
      if (r >= rows) continue;
      const float* Arow = A + (size_t)(row_start + r) * K;
      float local = 0.0f;
      for (int i = rem_start + lane_id; i < K; i += WARP_SIZE) {
        local += Arow[i] * B[i];
      }
      sum[rr] += local;
    }
  }
  // Warp-level reduction per row. Each warp exclusively owns its subset
  // of rows, so no block-wide shared-memory reduction step is needed.
  unsigned mask = 0xffffffffu;
  #pragma unroll
  for (int rr = 0; rr < ROWS_PER_WARP; ++rr) {
    int r = warp_id * ROWS_PER_WARP + rr;
    if (r >= rows) continue;
    float val = sum[rr];
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      val += __shfl_down_sync(mask, val, offset);
    }
    if (lane_id == 0) {
      atomicAdd(&C[row_start + r], val);
    }
  }
}

torch::Tensor cute_gemv_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be 2D (K, 1)");
  TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match (A.size(1) == B.size(0))");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  int M = (int)A_c.size(0);
  int K = (int)A_c.size(1);

  auto C = torch::zeros({M, 1}, A.options());

  const float* ptrA = A_c.data_ptr<float>();
  const float* ptrB = B_c.data_ptr<float>();
  float* ptrC = C.data_ptr<float>();

  dim3 block(256);
  dim3 grid((unsigned)((M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK), (unsigned)SPLIT_K);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemv_kernel<<<grid, block, 0, stream>>>(ptrA, ptrB, ptrC, M, K);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gemv_kernel launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_gemv = load_inline(
    name="cute_gemv_inline",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_gemv_forward"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"
    ],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom
    CuTe-based CUDA kernel: one block per output row, vectorized float4
    loads over K, and warp/block level tree reduction.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_gemv

